UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"Leukostasis Management","body":"**Step 1 — Hydration + TLS Prophylaxis:** [16][17]\n* IV fluids (NS, avoid LR)\n* **[Allopurinol](#/drug/allopurinol/tls)** 300 mg PO daily OR rasburicase if uric acid >8 (anticipate TLS as cells lyse)\n* Strict I/O\n\n**Step 2 — Cytoreduction:**\n\n**Hydroxyurea (first-line if available):**\n* **[Hydroxyurea](#/drug/hydroxyurea/leukostasis)** 50-100 mg/kg/day PO divided BID-TID\n* Drops WBC by 50-80% within 24-48 hours\n* Continued until induction chemo started\n\n**Leukapheresis:**\n* Indicated for severe leukostasis (especially neuro/respiratory)\n* Drops WBC 30-60% in single session\n* **CONTRAINDICATED in APL (acute promyelocytic leukemia, M3 AML)** — can precipitate severe DIC [35]\n* Bridge to definitive induction chemo\n\n**Definitive — Induction chemotherapy** (oncology drives this) — only definitive treatment\n\n**Step 3 — Avoid Pitfalls:**\n* **Hold packed RBC transfusions if possible** — increases viscosity, can worsen leukostasis (transfuse only if Hgb <7 or symptomatic anemia)\n* Diuretics worsen viscosity\n* Avoid nephrotoxic contrast if possible\n\n**Step 4 — Manage Comorbidities:**\n* TLS prophylaxis (see TLS module)\n* DIC if present\n* Respiratory failure may require intubation; consider ECMO bridge\n* Suspected APL → start [ATRA](#/drug/atra/apl) (all-trans retinoic acid) 45 mg/m²/day immediately on suspicion (do not wait for confirmation) [35]","citation":[16,17,35],"next":"onc-leuko-disposition","calculatorLinks":[{"id":"corrected-calcium","label":"Corrected Ca"}],"summary":"Leukostasis: hydration + allopurinol + hydroxyurea 50-100 mg/kg or leukapheresis (NOT in APL) + induction chemo; HOLD pRBCs"}'::jsonb
WHERE id = 'onc-leuko-treat' AND tree_id = 'oncological-emergencies';

-- Node: onc-leuko-disposition (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":7,"title":"Leukostasis — ICU Admit","body":"**Disposition:**\n* **Symptomatic leukostasis** → ICU\n* Heme/onc + apheresis service consults from ED\n* Continue hydration, allopurinol/rasburicase, hydroxyurea\n* Plan for leukapheresis (unless APL) or immediate induction\n* Strict transfusion stewardship\n* Monitor for TLS (often worsens with cytoreduction)\n\n**APL (suspected M3 AML):**\n* **DO NOT leukapheresis** — high DIC risk [35]\n* Start ATRA 45 mg/m²/day immediately on clinical suspicion [35]\n* Aggressive blood product support (cryo, FFP, platelets)\n* Coagulopathy is the leading cause of early death [35]","citation":[16,17,35],"recommendation":"**ICU. Continue hydration, allopurinol, hydroxyurea. Heme/apheresis consult. NO apheresis if APL — start ATRA immediately.**","confidence":"definitive","summary":"Leukostasis ICU: continue cytoreduction, watch for TLS; APL is the exception — no apheresis, ATRA immediately"}'::jsonb
