UPDATE decision_nodes SET data = '{"type":"result","module":11,"title":"ICI Myocarditis — Critical","body":"**Mortality 25-50%.** Suspect with any new chest pain, dyspnea, arrhythmia, or troponin elevation in ICI-treated patient. [28][29][31]\n\n**Workup:**\n• Troponin (high-sensitivity)\n• BNP\n• ECG (any new conduction abnormality is concerning)\n• Echocardiogram\n• Cardiac MRI if hemodynamically stable\n• **Endomyocardial biopsy** = definitive diagnosis\n• ID workup to rule out viral myocarditis\n\n**Management:**\n• **ICU admission immediately**\n• **[Methylprednisolone](#/drug/methylprednisolone/irae) 500-1000 mg IV daily × 3-5 days** (ESMO 2022; pulse) — earlier initiation correlates with lower MACE; taper after troponin <50% peak\n• **Steroid-refractory (≥50% are refractory): abatacept 10 mg/kg IV is the preferred second-line** [36] (CTLA4-Ig; emerging RCT evidence including phase III NCT05335928); ± **ruxolitinib** in fulminant disease — combined regimen showed mortality 3% vs 60% in early prospective study [36]\n• Other options if abatacept unavailable: mycophenolate 1g BID, IVIG, plasmapheresis, alemtuzumab; **avoid infliximab — increases mortality in CHF**\n• Anti-arrhythmics, mechanical support (IABP, ECMO) as needed\n• **Permanent ICI discontinuation**\n• **Cardiology consult immediately**\n\n**Concurrent myasthenia + myositis** can occur — check CK, AChR antibodies, exam for weakness/ptosis.","citation":[28,29,31,36],"recommendation":"**ICI myocarditis: ICU + methylpred 500-1000 mg IV daily x 3-5d (start within 24h) + cards consult; abatacept 10 mg/kg if steroid-refractory (avoid infliximab in CHF); permanent ICI d/c; check CK + AChR Ab for triple syndrome.**","confidence":"definitive","summary":"ICI myocarditis: 25-50% mortality; trop + ECG + echo + MRI + biopsy; ICU + methylpred 500-1000 mg IV x3-5d (early!); abatacept if refractory; permanent d/c","safetyLevel":"critical"}'::jsonb
WHERE id = 'onc-ici-myocarditis' AND tree_id = 'oncological-emergencies';

-- Node: onc-chemo-reference (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":12,"title":"Chemotherapy Reference — Nadirs & Toxicities","body":"[Comprehensive Chemotherapy Regimens & Side Effects](#/info/chemo-regimens)\n\n**ED-Critical Toxicity Patterns:**\n\n**Cardiotoxicity:**\n* Anthracyclines (doxorubicin, daunorubicin) — cumulative dose-dependent CHF\n* Trastuzumab — reversible LV dysfunction\n* 5-FU, capecitabine — coronary vasospasm\n* Immune checkpoint inhibitors — myocarditis (rare but lethal)\n\n**Pulmonary:**\n* Bleomycin — pulmonary fibrosis (avoid high FiO2)\n* Methotrexate — pneumonitis\n* Checkpoint inhibitors — pneumonitis (steroids)\n\n**Nephrotoxicity:**\n* Cisplatin — tubular injury\n* Methotrexate — crystalluria (alkalinize, leucovorin rescue)\n* Ifosfamide — Fanconi syndrome\n\n**Neurotoxicity:**\n* Vincristine — peripheral neuropathy, never IT (fatal)\n* Oxaliplatin — cold-triggered dysesthesia\n* Ifosfamide — encephalopathy (methylene blue rescue) [34]\n* Cisplatin — ototoxicity\n\n**Hematologic Nadirs:**\n* Most cytotoxics: nadir day 7-14, recovery day 21-28\n* Carboplatin/cisplatin: nadir day 14-21\n* Mitomycin: delayed nadir day 28-42\n* Always check date of last cycle and nadir expectation\n\n**Immune-Related Adverse Events (ICI):**\n* Can occur weeks to months after dose\n* Colitis (steroids + infliximab if refractory)\n* Hepatitis\n* Endocrinopathies (thyroiditis, hypophysitis, adrenalitis)\n* Pneumonitis\n* Myocarditis\n\n**Extravasation Emergencies:**\n* Anthracyclines, vinca alkaloids → severe tissue necrosis\n* Stop infusion, aspirate, do NOT flush\n* Anthracycline: dexrazoxane antidote within 6h [33]\n* Vinca: hyaluronidase + warm compress [33]\n* Mitomycin: cold compress + DMSO [33]","citation":[18,19,33,34],"next":"onc-disposition-summary","summary":"Chemo toxicities: cardiotox (anthracyclines), pulm (bleo), neuro (vinca), nadir d7-14; ICI = irAEs weeks-months later"}'::jsonb
WHERE id = 'onc-chemo-reference' AND tree_id = 'oncological-emergencies';

